// Generated by lib/generate-noun.ts from qsm.json. Do not hand-edit; run
// `bun lib/generate-noun.ts plugins/<name>` again after changing qsm.json.

export type Langdev = {
  check(options: {
    dir?: string;
    path?: (string)[];
    against?: string;
    at?: "pre-commit" | "pre-push";
    lang?: string;
    allFindings?: boolean;
  }): Promise<unknown>;
  list(): Promise<unknown>;
  doctor(options: {
    dir?: string;
  }): Promise<unknown>;
  languages(options: {
    action?: "list" | "add" | "remove";
    name?: string;
  }): Promise<unknown>;
  init(options: {
    dir?: string;
    profile?: string;
    target?: (string)[];
  }): Promise<unknown>;
  structure(options: {
    path?: string;
    against?: string;
    session?: string;
    agent?: string;
  }): Promise<unknown>;
  install(options: {
    dir?: string;
    lang?: "sh" | "py" | "ts";
  }): Promise<unknown>;
  uninstall(options: {
    dir?: string;
  }): Promise<unknown>;
  edited(options: {
    file: string;
    session: string;
    agent?: string;
  }): Promise<unknown>;
  hook(options: {
    name: "pre-commit" | "pre-push";
  }): Promise<unknown>;
};

declare module 'claude-code' {
  interface EngineInterface {
    langdev: Langdev;
  }
}
